mkdir -p /tmp/km_crash && cat > /tmp/km_crash/fakehsm.py <<'EOF'
"""External KMS/HSM provider for crash-recovery tests (module:factory)."""
import json, os, uuid

_REG = os.path.join(os.environ["FAKEHSM_DIR"], "registry.json")


def _load():
    try:
        with open(_REG) as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


def _save(reg):
    tmp = _REG + ".tmp"
    with open(tmp, "w") as f:
        json.dump(reg, f)
        f.flush()
        os.fsync(f.fileno())
    os.chmod(tmp, 0o600)
    os.replace(tmp, _REG)


class FakeHSM:
    provider_id = "fakehsm"
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": ["generate", "rotate", "import_material",
                       "export_material", "delete"],
    }

    def configure(self, data_dir):
        os.makedirs(os.environ["FAKEHSM_DIR"], exist_ok=True)

    def _mint(self, algorithm, public_key, material):
        h = "h-" + uuid.uuid4().hex
        reg = _load()
        reg[h] = {"algorithm": algorithm, "public_key": public_key,
                  "material": material}
        _save(reg)
        return {"handle": h, "public_key": public_key,
                "encrypted_material": material}

    def generate(self, algorithm):
        if os.environ.get("FAKEHSM_CALL_FAIL"):
            raise RuntimeError("backend generate down")
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.primitives import serialization
        if algorithm == "AES256":
            return self._mint("AES256", None, os.urandom(32).hex())
        key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        pub = key.public_key().public_bytes(
            serialization.Encoding.PEM,
            serialization.PublicFormat.SubjectPublicKeyInfo).decode()
        priv = key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.PKCS8RawKeyBytes,
            serialization.NoEncryption()).hex()
        return self._mint("RSA2048", pub, priv)

    def rotate(self, algorithm):
        if os.environ.get("FAKEHSM_CALL_FAIL"):
            raise RuntimeError("backend rotate down")
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        if os.environ.get("FAKEHSM_CALL_FAIL"):
            raise RuntimeError("backend import down")
        return self._mint(algorithm, public_key, material)

    def export_material(self, handle):
        reg = _load()
        if handle not in reg:
            raise RuntimeError("no such handle")
        return {"public_key": reg[handle]["public_key"],
                "encrypted_material": reg[handle]["material"]}

    def delete(self, handle):
        if os.environ.get("FAKEHSM_DELETE_FAIL"):
            raise RuntimeError("backend delete down")
        reg = _load()
        reg.pop(handle, None)
        _save(reg)


def factory():
    return FakeHSM()
